records.source_line:
  return `$ORIGIN ${domain}.
$TTL 300
@ IN SOA ns.${domain}. hostmaster.${domain}. ( ${dns.serial} 300 120 604800 300 )
@ IN NS ns.${domain}.
@ IN A ${dns.ipv4}
ns IN A ${dns.ipv4}
${dns.ipv6 ? `@ IN AAAA ${dns.ipv6}
ns IN AAAA ${dns.ipv6}
` : ""}${txt}`;

  return `${dns.tsig_ref ? 'include "/tmp/dns-tsig.conf";
' : ""}options {
 directory "/var/cache/bind";
 pid-file "/tmp/named.pid";
 session-keyfile "/tmp/session.key";
 listen-on port ${listen_port} { ${ipv4.length ? ipv4.map((value) => value === "0.0.0.0" ? "any" : value).join("; ") + ";" : "none;"} };
 listen-on-v6 port ${listen_port} { ${ipv6.length ? ipv6.map((value) => value === "::" ? "any" : value).join("; ") + ";" : "none;"} };
 recursion ${dns.recursion ? "yes" : "no"};
 allow-query { ${dns.clients.join("; ")}; };
 allow-query-cache { ${dns.recursion ? dns.clients.join("; ") : "none"}; };
 allow-recursion { ${dns.recursion ? dns.clients.join("; ") : "none"}; };
 ${dns.recursion ? `forward only; forwarders { ${dns.forwarders.join("; ")}; };` : ""}
 dnssec-validation no;
 empty-zones-enable no;
 version "not disclosed";
};
controls {};
zone "${domain}" { type primary; file "/var/cache/bind/${zoneFile(domain, dns, dkim).file}"; allow-update { none; }; allow-transfer { ${dns.tsig_ref ? 'key "infra-tsig"' : "none"}; }; notify no; };
`;

function location(selector, lines) { return `  location ${selector} {
${lines.map((line) => `    ${line}`).join("
")}
  }`; }
